/*
 * Glyph starter kit · the visual craft baseline as plain CSS.
 * Use: add class "g" to the page wrapper and optionally data-direction="…"
 * (see references/starter-kit.md). Load the fonts your direction names.
 * Licence: MIT, as part of the Glyph skill.
 */
.g {
  --g-bg: #fff;
  --g-fg: #0a0a0a;
  --g-muted: #5f6368;
  --g-raised: #f6f6f5;
  --g-card: #fff;
  --g-line: rgba(0, 0, 0, 0.08);
  --g-border: 1px;
  --g-accent: #0a0a0a;
  --g-on-accent: #fff;
  --g-font: "Inter Variable", "Inter", system-ui, sans-serif;
  --g-display: var(--g-font);
  --g-display-weight: 500;
  --g-display-tracking: -0.045em;
  --g-display-case: none;
  --g-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, monospace;
  --g-btn-radius: 10px;
  --g-radius: 20px;
  --g-radius-lg: 24px;
  --g-btn-shadow: none;
  --g-shadow: 0 1px 2px rgba(0, 0, 0, 0.04), 0 16px 40px -16px rgba(0, 0, 0, 0.16);
  background: var(--g-bg);
  color: var(--g-fg);
  font: 400 16px/1.6 var(--g-font);
  -webkit-font-smoothing: antialiased;
  overflow-x: clip;
}
.g h1,
.g h2,
.g h3 {
  font-family: var(--g-display);
  font-weight: var(--g-display-weight);
  text-transform: var(--g-display-case);
  text-wrap: balance;
}
.g p {
  margin: 0;
}
.g-wrap {
  width: min(1200px, 100% - 48px);
  margin-inline: auto;
}

/* Header */
.g-header {
  position: sticky;
  top: 0;
  z-index: 40;
  background: color-mix(in srgb, var(--g-bg) 80%, transparent);
  backdrop-filter: saturate(1.4) blur(14px);
  border-bottom: 1px solid var(--g-line);
}
.g-header .g-wrap {
  display: flex;
  align-items: center;
  height: 64px;
  gap: 32px;
}
.g-logo {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-weight: 600;
  font-size: 15px;
  letter-spacing: -0.02em;
  color: inherit;
  text-decoration: none;
}
.g-nav {
  display: flex;
  gap: 28px;
  font-size: 14px;
}
.g-nav a,
.g-header-links a:not(.g-btn) {
  color: var(--g-muted);
  text-decoration: none;
  transition: color 150ms;
}
.g-nav a:hover,
.g-header-links a:not(.g-btn):hover {
  color: var(--g-fg);
}
.g-header-links {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 20px;
  font-size: 14px;
}

/* Controls */
.g-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 40px;
  padding: 0 16px;
  border: 1px solid transparent;
  border-radius: var(--g-btn-radius);
  font: 500 14px/1 var(--g-font);
  letter-spacing: -0.005em;
  white-space: nowrap;
  text-decoration: none;
  cursor: pointer;
  transition:
    background-color 150ms,
    border-color 150ms,
    transform 120ms;
}
.g-btn:active {
  transform: scale(0.98);
}
.g-btn-primary {
  background: var(--g-accent);
  color: var(--g-on-accent);
  box-shadow: var(--g-btn-shadow);
}
.g-btn-primary:hover {
  background: color-mix(in srgb, var(--g-accent) 86%, var(--g-bg));
}
.g-btn-secondary {
  background: var(--g-card);
  border-color: var(--g-line);
  color: var(--g-fg);
}
.g-btn-secondary:hover {
  background: var(--g-raised);
}
.g-btn-lg {
  height: 44px;
  padding: 0 20px;
  font-size: 15px;
}
.g-btn-sm {
  height: 34px;
  padding: 0 12px;
  font-size: 13px;
}
.g-input {
  height: 44px;
  padding: 0 14px;
  border: var(--g-border) solid var(--g-line);
  border-radius: var(--g-btn-radius);
  background: var(--g-card);
  color: var(--g-fg);
  font: 400 15px var(--g-font);
}
.g a:focus-visible,
.g button:focus-visible,
.g input:focus-visible,
.g summary:focus-visible {
  outline: 2px solid var(--g-accent);
  outline-offset: 2px;
}

/* Hero */
.g-hero {
  padding: 120px 0 0;
  text-align: center;
}
.g-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 30px;
  padding: 0 12px 0 4px;
  border: var(--g-border) solid var(--g-line);
  border-radius: 999px;
  background: var(--g-card);
  font-size: 13px;
  font-weight: 500;
  color: var(--g-muted);
  text-decoration: none;
}
.g-pill b {
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--g-raised);
  color: var(--g-fg);
  font-weight: 500;
  font-size: 12px;
}
.g-display {
  margin: 24px auto 20px;
  max-width: 820px;
  font-size: clamp(42px, 5.4vw, 70px);
  line-height: 1.04;
  letter-spacing: var(--g-display-tracking);
}
.g .g-lede {
  max-width: 560px;
  margin: 0 auto;
  font-size: 18px;
  line-height: 1.55;
  color: var(--g-muted);
}
.g-actions {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 32px;
  flex-wrap: wrap;
}
.g .g-proof {
  margin-top: 16px;
  font-size: 13px;
  color: var(--g-muted);
}

/* Media frame */
.g-frame {
  position: relative;
  border-radius: var(--g-radius-lg);
  overflow: hidden;
  isolation: isolate;
}
.g-frame-art {
  position: absolute;
  inset: 0;
  z-index: -1;
}
.g-window {
  border: var(--g-border) solid var(--g-line);
  border-radius: 14px;
  background: var(--g-card);
  box-shadow: var(--g-shadow);
  overflow: hidden;
  text-align: left;
}
.g-window-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 36px;
  padding: 0 14px;
  border-bottom: 1px solid var(--g-line);
  background: var(--g-raised);
}
.g-window-bar i {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--g-fg) 18%, transparent);
}

/* Sections */
.g-section {
  padding: 120px 0;
}
.g-section + .g-section {
  border-top: 1px solid var(--g-line);
}
.g-head {
  max-width: 600px;
  margin: 0 auto 56px;
  text-align: center;
}
.g-eyebrow {
  font-size: 13px;
  font-weight: 500;
  color: var(--g-muted);
}
.g-h2 {
  margin: 12px 0 14px;
  font-size: clamp(32px, 3.6vw, 44px);
  line-height: 1.1;
  letter-spacing: -0.035em;
}
.g-head p {
  color: var(--g-muted);
  font-size: 17px;
}

/* Bento */
.g-bento {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 16px;
}
.g-card {
  display: flex;
  flex-direction: column;
  border: var(--g-border) solid var(--g-line);
  border-radius: var(--g-radius);
  background: var(--g-card);
  overflow: hidden;
}
.g-card-visual {
  position: relative;
  flex: 1;
  min-height: 220px;
  padding: 24px;
  background: var(--g-raised);
  border-bottom: 1px solid var(--g-line);
  overflow: hidden;
}
.g-card-body {
  padding: 24px 28px 28px;
}
.g-card h3 {
  margin: 0 0 6px;
  font-size: 18px;
  line-height: 1.3;
  letter-spacing: -0.015em;
}
.g-card p {
  font-size: 15px;
  color: var(--g-muted);
}
.g-span-7 {
  grid-column: span 7;
}
.g-span-5 {
  grid-column: span 5;
}
.g-span-6 {
  grid-column: span 6;
}
.g-span-4 {
  grid-column: span 4;
}

/* Steps */
.g-steps {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.g-steps li {
  padding: 28px;
  border: var(--g-border) solid var(--g-line);
  border-radius: var(--g-radius);
  background: var(--g-card);
}
.g-steps span {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: var(--g-raised);
  font-size: 13px;
  font-weight: 600;
}
.g-steps h3 {
  margin: 20px 0 6px;
  font-size: 18px;
  letter-spacing: -0.015em;
}
.g-steps p {
  color: var(--g-muted);
  font-size: 15px;
}

/* Pricing */
.g-pricing {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  align-items: stretch;
}
.g-plan {
  display: flex;
  flex-direction: column;
  padding: 28px;
  border: var(--g-border) solid var(--g-line);
  border-radius: var(--g-radius);
  background: var(--g-card);
}
.g-plan.is-featured {
  border-color: var(--g-fg);
  box-shadow: var(--g-shadow);
}
.g-plan h3 {
  margin: 0;
  font-size: 16px;
  letter-spacing: -0.01em;
}
.g-plan > p {
  color: var(--g-muted);
  font-size: 14px;
  margin-top: 4px;
}
.g-price {
  margin: 24px 0;
  font-size: 40px;
  font-weight: 500;
  letter-spacing: -0.04em;
  line-height: 1;
}
.g-price small {
  font-size: 14px;
  font-weight: 400;
  color: var(--g-muted);
  letter-spacing: 0;
}
.g-plan ul {
  list-style: none;
  margin: 24px 0 0;
  padding: 24px 0 0;
  border-top: 1px solid var(--g-line);
  display: grid;
  gap: 10px;
  font-size: 14px;
}
.g-plan li {
  display: flex;
  gap: 10px;
  align-items: start;
}
.g-plan li svg {
  margin-top: 3px;
  color: var(--g-muted);
}

/* FAQ */
.g-faq {
  max-width: 760px;
  margin: 0 auto;
  border-top: 1px solid var(--g-line);
}
.g-faq details {
  border-bottom: 1px solid var(--g-line);
}
.g-faq summary {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 20px 0;
  font-weight: 500;
  cursor: pointer;
  list-style: none;
}
.g-faq summary::-webkit-details-marker {
  display: none;
}
.g-faq summary::after {
  content: "+";
  font-size: 20px;
  font-weight: 300;
  color: var(--g-muted);
  transition: transform 150ms;
}
.g-faq details[open] summary::after {
  transform: rotate(45deg);
}
.g-faq details p {
  padding: 0 0 20px;
  color: var(--g-muted);
  max-width: 62ch;
}

/* Final CTA */
.g-cta {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  padding: 96px 32px;
  border-radius: var(--g-radius-lg);
  text-align: center;
}
.g-cta .g-h2 {
  margin-top: 0;
}

/* Footer */
.g-footer {
  padding: 64px 0 40px;
  border-top: 1px solid var(--g-line);
  font-size: 14px;
}
.g-footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 32px;
}
.g-footer p,
.g-footer a {
  color: var(--g-muted);
  text-decoration: none;
}
.g-footer a:hover {
  color: var(--g-fg);
}
.g-footer h4 {
  margin: 0 0 14px;
  font-size: 13px;
  font-weight: 500;
}
.g-footer ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 10px;
}
.g-footer-legal {
  display: flex;
  justify-content: space-between;
  margin-top: 56px;
  padding-top: 24px;
  border-top: 1px solid var(--g-line);
  font-size: 13px;
  color: var(--g-muted);
}

/* Entrance */
@keyframes g-rise {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
}
.g-rise {
  animation: g-rise 700ms cubic-bezier(0.2, 0.7, 0.2, 1) both;
}
.g-rise-2 {
  animation-delay: 80ms;
}
.g-rise-3 {
  animation-delay: 160ms;
}
.g-rise-4 {
  animation-delay: 240ms;
}
@media (prefers-reduced-motion: reduce) {
  .g-rise {
    animation: none;
  }
}

@media (max-width: 960px) {
  .g-nav {
    display: none;
  }
  .g-span-7,
  .g-span-5,
  .g-span-6,
  .g-span-4 {
    grid-column: span 12;
  }
  .g-steps,
  .g-pricing {
    grid-template-columns: 1fr;
  }
  .g-footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}
@media (max-width: 640px) {
  .g-wrap {
    width: calc(100% - 40px);
  }
  .g-header-links .g-hide-sm {
    display: none;
  }
  .g-hero {
    padding-top: 72px;
  }
  .g-display {
    font-size: 40px;
    letter-spacing: -0.04em;
  }
  .g-lede {
    font-size: 16px;
  }
  .g-section {
    padding: 80px 0;
  }
  .g-h2 {
    font-size: 30px;
  }
  .g-head {
    margin-bottom: 40px;
  }
  .g-cta {
    padding: 64px 20px;
  }
  .g-footer-legal {
    flex-direction: column;
    gap: 8px;
  }
}

/* Extra sections */
.g-logos {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 16px 48px;
  opacity: 0.55;
  font-size: 15px;
  font-weight: 600;
}
.g-metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  text-align: center;
}
.g-metrics strong {
  display: block;
  font: var(--g-display-weight) clamp(36px, 4vw, 52px) / 1 var(--g-display);
  letter-spacing: var(--g-display-tracking);
}
.g-metrics span {
  font-size: 14px;
  color: var(--g-muted);
}
.g-quote {
  padding: 28px;
  border: var(--g-border) solid var(--g-line);
  border-radius: var(--g-radius);
  background: var(--g-card);
}
.g-quote blockquote {
  margin: 0 0 20px;
  font-size: 17px;
  line-height: 1.5;
}
.g-quote figcaption {
  font-size: 14px;
  color: var(--g-muted);
}
.g-split {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 64px;
  align-items: center;
  text-align: left;
}
.g-split .g-display,
.g-split .g-lede {
  margin-left: 0;
}
.g-split .g-actions {
  justify-content: start;
}
.g-fullbleed {
  position: relative;
  isolation: isolate;
  display: grid;
  align-items: end;
  min-height: min(92vh, 900px);
  padding: 120px 0 64px;
  color: #fff;
  overflow: hidden;
}
.g-fullbleed > img,
.g-fullbleed > video,
.g-fullbleed > .g-frame-art {
  position: absolute;
  inset: 0;
  z-index: -2;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.g-fullbleed::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(0deg, rgba(0, 0, 0, 0.65), rgba(0, 0, 0, 0) 60%);
}
.g-marquee {
  display: flex;
  gap: 48px;
  overflow: hidden;
  white-space: nowrap;
  font: var(--g-display-weight) clamp(40px, 7vw, 96px) / 1 var(--g-display);
  text-transform: var(--g-display-case);
  letter-spacing: var(--g-display-tracking);
}
.g-marquee > span {
  animation: g-marquee 30s linear infinite;
}
@keyframes g-marquee {
  to {
    transform: translateX(-100%);
  }
}
.g-phone {
  width: 300px;
  height: 640px;
  padding: 10px;
  border-radius: 52px;
  background: #111;
  box-shadow:
    inset 0 0 0 1.5px #3f3f46,
    0 40px 80px -24px rgba(0, 0, 0, 0.45);
}
.g-phone > * {
  height: 100%;
  border-radius: 42px;
  overflow: hidden;
  background: var(--g-card);
}
@media (prefers-reduced-motion: reduce) {
  .g-marquee > span {
    animation: none;
  }
}
@media (max-width: 960px) {
  .g-split {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .g-metrics {
    grid-template-columns: 1fr 1fr;
  }
}

/* Direction presets: tokens only. Pair with the fonts named in style-directions.md. */
.g[data-direction="dark-technical"] {
  --g-bg: #000;
  --g-fg: #fafafa;
  --g-muted: #a1a1aa;
  --g-raised: #0e0e10;
  --g-card: #09090b;
  --g-line: rgba(255, 255, 255, 0.09);
  --g-accent: #fafafa;
  --g-on-accent: #000;
  --g-font: "Geist Variable", "Geist", "Inter", system-ui, sans-serif;
  --g-shadow: 0 0 0 1px rgba(255, 255, 255, 0.04), 0 30px 80px -20px rgba(0, 0, 0, 0.9);
}
.g[data-direction="luminous"] {
  --g-bg: #fbfbfe;
  --g-raised: #f2f1fb;
  --g-accent: #18181b;
  --g-btn-radius: 999px;
  --g-radius: 28px;
  --g-radius-lg: 32px;
  --g-font: "Inter Variable", "Sora", system-ui, sans-serif;
}
.g[data-direction="editorial"] {
  --g-bg: #f7f5f0;
  --g-raised: #efece4;
  --g-card: #f7f5f0;
  --g-fg: #161513;
  --g-muted: #5c5850;
  --g-line: rgba(22, 21, 19, 0.14);
  --g-accent: #161513;
  --g-display: "Instrument Serif", "Newsreader", Georgia, serif;
  --g-display-weight: 400;
  --g-display-tracking: -0.02em;
  --g-btn-radius: 0;
  --g-radius: 4px;
  --g-radius-lg: 4px;
  --g-shadow: none;
}
.g[data-direction="warm-organic"] {
  --g-bg: #f4ede2;
  --g-raised: #ebe1d1;
  --g-card: #fbf7f0;
  --g-fg: #2b1e17;
  --g-muted: #6a5447;
  --g-line: rgba(43, 30, 23, 0.12);
  --g-accent: #a9482a;
  --g-display: "Fraunces Variable", "Young Serif", Georgia, serif;
  --g-display-weight: 420;
  --g-display-tracking: -0.025em;
  --g-font: "Figtree Variable", "DM Sans", system-ui, sans-serif;
  --g-btn-radius: 999px;
  --g-radius: 24px;
  --g-radius-lg: 28px;
}
.g[data-direction="luxury"] {
  --g-bg: #f8f6f1;
  --g-raised: #efebe3;
  --g-card: #f8f6f1;
  --g-fg: #111;
  --g-muted: #6b665d;
  --g-line: rgba(17, 17, 17, 0.14);
  --g-accent: #111;
  --g-display: "Cormorant Garamond", "Bodoni Moda", Georgia, serif;
  --g-display-weight: 400;
  --g-display-tracking: -0.01em;
  --g-btn-radius: 0;
  --g-radius: 0;
  --g-radius-lg: 0;
  --g-shadow: none;
}
.g[data-direction="bold"] {
  --g-bg: #0b0b0b;
  --g-fg: #fff;
  --g-muted: #bdbdbd;
  --g-raised: #161616;
  --g-card: #121212;
  --g-line: rgba(255, 255, 255, 0.14);
  --g-accent: #ff4f2b;
  --g-on-accent: #fff;
  --g-display: "Anton", "Bebas Neue", "Archivo", Impact, sans-serif;
  --g-display-weight: 400;
  --g-display-tracking: 0;
  --g-display-case: uppercase;
  --g-btn-radius: 999px;
}
.g[data-direction="playful"] {
  --g-bg: #fffaf0;
  --g-raised: #fff1d6;
  --g-fg: #1b1b1f;
  --g-line: #1b1b1f;
  --g-border: 2px;
  --g-accent: #6c4cff;
  --g-display: "Bricolage Grotesque Variable", "Syne", system-ui, sans-serif;
  --g-display-weight: 700;
  --g-display-tracking: -0.04em;
  --g-btn-radius: 999px;
  --g-radius: 28px;
  --g-btn-shadow: 3px 3px 0 #1b1b1f;
  --g-shadow: 6px 6px 0 #1b1b1f;
}
.g[data-direction="brutalist"] {
  --g-bg: #fff;
  --g-fg: #000;
  --g-muted: #333;
  --g-raised: #f0f0f0;
  --g-line: #000;
  --g-border: 2px;
  --g-accent: #0000ff;
  --g-font: "Space Grotesk Variable", "Space Grotesk", "Archivo", Arial, sans-serif;
  --g-mono: "Space Mono", ui-monospace, monospace;
  --g-display-weight: 700;
  --g-display-tracking: -0.03em;
